function formatHundreds(num: string): string {
    if (num.length > 3) {
        const length: number = num.length;
        const hundreds: string = num.slice(length - 3, length);
        let thousands: string = num.slice(0, length - 3);
        thousands = formatHundreds(thousands);
        num = `${thousands}.${hundreds}`;
    }
    return num;
}

export function formatNumber(prize: number | undefined, maxLength?: number): string {
    const prizeString: string = prize ? prize.toString() : '0';

    switch (true) {
        case prizeString.length === 1:
            return `0,0${prizeString}`;
        case prizeString.length === 2:
            return `0,${prizeString}`;
        default:
            const length: number = prizeString.length;
            const remainder: string = prizeString.slice(length - 2, length);
            let whole: string = prizeString.slice(0, length - 2);
            whole = formatHundreds(whole);
            if (maxLength && length >= maxLength) {
                return `${whole}`;
            }

            return `${whole},${remainder}`;
    }
}

